package com.trace.refract.util;

import com.trace.refract.module.ModuleManager;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.sound.PositionedSoundInstance;
import net.minecraft.sound.SoundEvent;
import net.minecraft.util.Identifier;

/**
 * Refract's own interface sounds (synthesized OGGs in assets/refract/sounds/ui, generated by tools/gen_sounds.py).
 * They are looked up by id from sounds.json and never registered, so joining any server is unaffected.
 * Played locally only; muted with Click GUI > UI Sounds.
 */
public final class Sfx {
    private static long lastHover;

    private Sfx() {}

    private static SoundEvent ev(String name) { return SoundEvent.of(Identifier.of("refract", "ui." + name)); }

    private static final SoundEvent CLICK = ev("click"), HOVER = ev("hover"), ON = ev("toggle_on"), OFF = ev("toggle_off"),
            OPEN = ev("open"), CLOSE = ev("close"), FOCUS = ev("focus"), ALERT = ev("alert"), NOTIFY = ev("notify"), WARN = ev("warn");

    private static void play(SoundEvent e, float volume) {
        if (ModuleManager.clickGui == null || !ModuleManager.clickGui.sounds.on()) return;
        MinecraftClient mc = MinecraftClient.getInstance();
        if (mc.getSoundManager() == null) return;
        mc.getSoundManager().play(PositionedSoundInstance.ui(e, 1f, volume * ModuleManager.clickGui.volume.asFloat()));
    }

    public static void click() { play(CLICK, 0.8f); }

    public static void toggle(boolean on) { play(on ? ON : OFF, 0.8f); }

    /** Soft tick when the pointer moves onto something new; rate-limited so sweeping is not noisy. */
    public static void hover() {
        long now = System.currentTimeMillis();
        if (now - lastHover < 60) return;
        lastHover = now;
        play(HOVER, 0.6f);
    }

    public static void open() { play(OPEN, 0.8f); }

    public static void close() { play(CLOSE, 0.7f); }

    /** Rising three-note chime for a new finding. */
    public static void alert() { play(ALERT, 1f); }

    public static void notifySoft() { play(NOTIFY, 0.8f); }

    public static void warn() { play(WARN, 1f); }

    public static void focus() { play(FOCUS, 0.7f); }
}
